(()=>{
const reduced=()=>document.body.classList.contains('motion-off')||matchMedia('(prefers-reduced-motion: reduce)').matches;
document.querySelectorAll('.war-console,.event-console').forEach(el=>{const grid=document.createElement('div');grid.className='hyper-grid';grid.setAttribute('aria-hidden','true');el.prepend(grid);const signal=document.createElement('div');signal.className='hyper-signal';signal.setAttribute('aria-hidden','true');signal.innerHTML=`<span class="hyper-spectrum">${Array.from({length:16},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</span><span>STRATEGY / SIGNAL / EXECUTION</span>`;el.append(signal)});
// Animate only real historical figures; never generate synthetic live metrics.
const targets=document.querySelectorAll('.event-kpis strong');const seen=new WeakSet();const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting||seen.has(e.target))return;seen.add(e.target);observer.unobserve(e.target);if(reduced())return;const el=e.target,text=Array.from(el.childNodes).find(n=>n.nodeType===Node.TEXT_NODE&&/[0-9]/.test(n.textContent));if(!text)return;const original=text.textContent,end=Number(original.replace(/,/g,''));let start;function frame(t){if(!start)start=t;let p=Math.min((t-start)/1100,1);text.textContent=reduced()||p===1?original:Math.round(end*(1-Math.pow(1-p,3))).toLocaleString('zh-TW');if(p<1&&!reduced())requestAnimationFrame(frame)}requestAnimationFrame(frame)}),{threshold:.3});targets.forEach(t=>observer.observe(t));
})();
